interface IWBNB is IERC20 {
    function deposit() external payable;
}

interface IMoolah {
    function flashLoan(address token, uint256 amount, bytes calldata data) external;
}

interface IVenusComptroller {
    function enterMarkets(address[] calldata vTokens) external returns (uint256[] memory);
}

interface IVToken is IERC20 {
    function mint(uint256 mintAmount) external returns (uint256);
    function borrow(uint256 borrowAmount) external returns (uint256);
    function repayBorrow(uint256 repayAmount) external returns (uint256);
    function redeemUnderlying(uint256 redeemAmount) external returns (uint256);
}

interface IAavePool {
    function supply(address asset, uint256 amount, address onBehalfOf, uint16 referralCode) external;
    function borrow(address asset, uint256 amount, uint256 interestRateMode, uint16 referralCode, address onBehalfOf)
        external;
    function repay(address asset, uint256 amount, uint256 interestRateMode, address onBehalfOf)
        external
        returns (uint256);
    function withdraw(address asset, uint256 amount, address to) external returns (uint256);
}

interface IBalancerLock {
    function lock(bytes calldata data) external returns (bytes memory result);
    function take(address token, address to, uint256 amount) external;
    function sync(address token) external;
    function settle() external returns (uint256 credit);
}

interface IV3Pool {
    function flash(address recipient, uint256 amount0, uint256 amount1, bytes calldata data) external;
}

interface IPancakeRouter {
    function swapTokensForExactTokens(
        uint256 amountOut,
        uint256 amountInMax,
        address[] calldata path,
        address to,
        uint256 deadline
    ) external returns (uint256[] memory amounts);

    function swapExactTokensForTokensSupportingFeeOnTransferTokens(
        uint256 amountIn,
        uint256 amountOutMin,
        address[] calldata path,
        address to,
        uint256 deadline
    ) external;
}

interface IAROS is IERC20 {
    function claimPrincipal(
        uint256 periodFrom,
        uint256 periodTo,
        uint256 amount,
        uint256 deadline,
        bytes calldata signature
    ) external;

    function claimYield(
        uint256 periodFrom,
        uint256 periodTo,
        uint256 userAmount,
        address referralPool,
        uint256 referralAmount,
        address dividendPool,
        uint256 dividendAmount,
        uint256 deadline,
        bytes calldata signature
    ) external;
}


