            uint8 b = uint8(value & 0x7f);
            if (out.length != 0) b = uint8(uint256(b) | 0x80);
            out = bytes.concat(abi.encodePacked(b), out);
            if (value <= 0x7f) break;
            value = (value >> 7) - 1;
        }
    }
